            (if tmp1 then rel_guard else (let tmp2 = (FStarC_Errors.with_ctx "Typechecking decreases well-founded relation" (fun tmp2 -> ((env2).FStarC_TypeChecker_Env.typeof_well_typed_tot_or_gtot_term env2 rel false))) in
            (match tmp2 with
              | (t_rel, tmp3) -> (let tmp4 = (FStarC_Errors.with_ctx "Typechecking previous decreases well-founded relation" (fun tmp4 -> ((env2).FStarC_TypeChecker_Env.typeof_well_typed_tot_or_gtot_term env2 rel_prev false))) in
                (match tmp4 with
                  | (t_rel_prev, tmp5) -> (let eq_guard = (FStarC_Syntax_Util.mk_eq3_no_univ t_rel t_rel_prev rel rel_prev) in
                    (FStarC_Syntax_Util.mk_conj eq_guard rel_guard))
                ))
            ))))
          | (tmp, tmp1) -> (FStarC_Errors.fStarC_Errors_raise_error__range_string r FStarC_Errors_Codes.Fatal_UnexpectedTerm "Cannot build termination VC with a well-founded relation and lex ordering")
        )) in
      let previous_dec = (decreases_clause actuals expected_c) in
      let guard_one_letrec = (fun tmp -> (match tmp with
          | (l, arity, t, u_names) -> (let tmp1 = (FStarC_TypeChecker_Normalize.get_n_binders_no_unrefine env1 arity t) in
            (match tmp1 with
              | (formals, c) -> ((if (Prims.op_Greater arity (FStarC_List.length formals)) then (FStarC_Effect.failwith "impossible: bad formals arity, guard_one_letrec") else ());
                let formals1 = (FStarC_List.map (fun b -> (if (FStarC_Syntax_Syntax.is_null_bv (b).FStarC_Syntax_Syntax.binder_bv) then (let tmp2 = (FStarC_Syntax_Syntax.new_bv (Some ((FStarC_Syntax_Syntax.range_of_bv (b).FStarC_Syntax_Syntax.binder_bv))) ((b).FStarC_Syntax_Syntax.binder_bv).FStarC_Syntax_Syntax.sort) in
                  { FStarC_Syntax_Syntax.binder_bv = tmp2;
                    binder_qual = (b).FStarC_Syntax_Syntax.binder_qual;
                    binder_positivity = (b).FStarC_Syntax_Syntax.binder_positivity;
                    binder_attrs = (b).FStarC_Syntax_Syntax.binder_attrs }) else b)) formals) in
                let dec = (decreases_clause formals1 c) in
                let env2 = (FStarC_TypeChecker_Env.push_binders env1 formals1) in
                let precedes = (mk_precedes env2 dec previous_dec) in
                let precedes1 = (FStarC_TypeChecker_Util.label (FStarC_Errors_Msg.mkmsg "Could not prove termination of this recursive call") r precedes) in
                let env_formals = (FStarC_TypeChecker_Env.push_binders env1 formals1) in
                let tmp2 = ((guard_letrecs__split_trailing_pre is_precondition_binder env_formals) formals1) in
                (match tmp2 with
                  | (real_formals, pre_formals) -> (let refined_formals = (match real_formals with
                        | [] -> (let tmp3 = (FStarC_Util.prefix formals1) in
                          (match tmp3 with
                            | (bs, { FStarC_Syntax_Syntax.binder_bv = last; binder_qual = imp; binder_positivity = pqual; binder_attrs = attrs; _ }) -> (let tmp4 = (FStarC_Syntax_Util.refine last precedes1) in
                              let last1 = { FStarC_Syntax_Syntax.ppname = (last).FStarC_Syntax_Syntax.ppname;
                                  index = (last).FStarC_Syntax_Syntax.index;
                                  sort = tmp4 } in
                              (FStarC_List.op_At bs ((FStarC_Syntax_Syntax.mk_binder_with_attrs last1 imp pqual attrs) :: [])))
                          ))
                        | tmp3 -> (let tmp4 = (FStarC_Util.prefix real_formals) in
                          (match tmp4 with
                            | (bs, { FStarC_Syntax_Syntax.binder_bv = last; binder_qual = imp; binder_positivity = pqual; binder_attrs = attrs; _ }) -> (let tmp5 = (FStarC_Syntax_Util.refine last precedes1) in
                              let last1 = { FStarC_Syntax_Syntax.ppname = (last).FStarC_Syntax_Syntax.ppname;
                                  index = (last).FStarC_Syntax_Syntax.index;
                                  sort = tmp5 } in
                              (FStarC_List.op_At bs (FStarC_List.op_At ((FStarC_Syntax_Syntax.mk_binder_with_attrs last1 imp pqual attrs) :: []) pre_formals)))
                          ))
                      ) in
                    let t' = (FStarC_Syntax_Util.arrow refined_formals c) in
                    let tmp3 = (FStarC_Debug.medium ()) in
                    (if tmp3 then (let tmp4 = (FStarC_Syntax_Print.fStarC_Class_Show_show__either_bv_fv l) in
                    let tmp5 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' t) in
                    let tmp6 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' t') in
                    (FStarC_Format.print3 "Refined let rec %s\n\tfrom type %s\n\tto type %s\n" tmp4 tmp5 tmp6)) else ());
                    (l, t', u_names))
                ))
            ))
        )) in
      (FStarC_List.map guard_one_letrec letrecs))
  )

