let check_expected_effect (env : FStarC_TypeChecker_Env.env) (use_eq : bool) (copt : ((FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) option) (ec : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax)) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax * FStarC_TypeChecker_Common.guard_t) =
  (match ec with
    | (e, c) -> (let tot_or_gtot = (fun c1 -> (let tmp = (FStarC_Syntax_Util.is_pure_comp c1) in
        (if tmp then (FStarC_Syntax_Syntax.mk_Total (FStarC_Syntax_Util.comp_result c1)) else (let tmp1 = (FStarC_Syntax_Util.is_pure_or_ghost_comp c1) in
        (if tmp1 then (FStarC_Syntax_Syntax.mk_GTotal (FStarC_Syntax_Util.comp_result c1)) else (FStarC_Effect.failwith "Impossible: Expected pure_or_ghost comp")))))) in
      let tmp = (match copt with
          | (Some (tmp)) -> (copt, c, None)
          | None -> (let tmp = (FStarC_Syntax_Util.is_tot_or_gtot_comp c) in
            (if tmp then (let tmp1 = (tot_or_gtot c) in
            (None, tmp1, None)) else (let tmp1 = (FStarC_Syntax_Util.is_pure_or_ghost_comp c) in
            (if tmp1 then (let tmp2 = (tot_or_gtot c) in
            let tmp3 = (Some (tmp2)) in
            (tmp3, c, None)) else (let tmp2 = (FStarC_Options.trivial_pre_for_unannotated_effectful_fns ()) in
            (if tmp2 then (let tmp3 = (FStarC_TypeChecker_Util.check_trivial_precondition_wp env c) in
            (match tmp3 with
              | (ct, tmp4, g) -> (let tmp5 = (FStarC_Syntax_Syntax.mk_Comp ct) in
                (None, tmp5, (Some (g))))
            )) else (None, c, None)))))))
        ) in
      (match tmp with
        | (expected_c_opt, c1, gopt) -> ((FStarC_TypeChecker_Env.fStarC_Defensive_def_check_scoped__env_syntax_comp' (c1).FStarC_Syntax_Syntax.pos "check_expected_effect.c.before_norm" env c1);
          let c2 = (FStarC_Errors.with_ctx "While normalizing actual computation type in check_expected_effect" (fun tmp1 -> (norm_c env c1))) in
          (FStarC_TypeChecker_Env.fStarC_Defensive_def_check_scoped__env_syntax_comp' (c2).FStarC_Syntax_Syntax.pos "check_expected_effect.c.after_norm" env c2);
          (match expected_c_opt with
            | None -> (e, c2, (match gopt with
                | None -> FStarC_TypeChecker_Common.fStarC_Class_Monoid_mzero__guard_t
                | (Some (g)) -> g
              ))
            | (Some (expected_c)) -> ((match gopt with
                | None -> ()
                | (Some (tmp1)) -> (FStarC_Effect.failwith "Impossible! check_expected_effect, gopt should have been None")
              );
              let c3 = (if use_eq then c2 else (FStarC_TypeChecker_Util.maybe_assume_result_eq_pure_term env e c2)) in
              let tmp1 = (c3, FStarC_TypeChecker_Env.trivial_guard) in
              (match tmp1 with
                | (c4, g_c) -> ((FStarC_TypeChecker_Env.fStarC_Defensive_def_check_scoped__env_syntax_comp' (c4).FStarC_Syntax_Syntax.pos "check_expected_effect.c.after_assume" env c4);
                  let tmp2 = (FStarC_Debug.medium ()) in
                  (if tmp2 then (let tmp3 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_term' e) in
                  let tmp4 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_comp' c4) in
                  let tmp5 = (FStarC_Syntax_Print.fStarC_Class_Show_show__syntax_comp' expected_c) in
                  let tmp6 = (FStarC_Class_Show.fStarC_Class_Show_show__bool use_eq) in
                  (FStarC_Format.print4 "In check_expected_effect, asking rel to solve the problem on e=(%s) and c=(%s), expected_c=(%s), and use_eq=%s\n" tmp3 tmp4 tmp5 tmp6)) else ());
                  let tmp3 = (FStarC_TypeChecker_Util.check_comp env use_eq e c4 expected_c) in
                  (match tmp3 with
                    | (e1, tmp4, g) -> (let g1 = (FStarC_TypeChecker_Util.label_guard (FStarC_TypeChecker_Env.get_range env) (FStarC_Errors_Msg.mkmsg "Could not prove post-condition") g) in
                      let tmp5 = (FStarC_Debug.medium ()) in
                      (if tmp5 then (let tmp6 = (FStarC_Range_Ops.string_of_range (e1).FStarC_Syntax_Syntax.pos) in
                      let tmp7 = (FStarC_TypeChecker_Rel.guard_to_string env g1) in
                      (FStarC_Format.print2 "(%s) DONE check_expected_effect;\n\tguard is: %s\n" tmp6 tmp7)) else ());
                      let e2 = (FStarC_TypeChecker_Util.maybe_lift env e1 (FStarC_Syntax_Util.comp_effect_name c4) (FStarC_Syntax_Util.comp_effect_name expected_c) (FStarC_Syntax_Util.comp_result c4)) in
                      let tmp6 = (FStarC_TypeChecker_Common.fStarC_Class_Monoid_op_Plus_Plus__guard_t g1 g_c) in
                      (e2, expected_c, tmp6))
                  ))
              ))
          ))
      ))
  )

let wrap_guard_with_tactic_opt (topt : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) option) (g : FStarC_TypeChecker_Common.guard_t) : FStarC_TypeChecker_Common.guard_t =
  (match topt with
    | None -> g
    | (Some (tactic)) -> (FStarC_TypeChecker_Env.always_map_guard g (fun g1 -> (let tmp = (FStarC_Syntax_Util.mk_squash g1) in
      (FStarC_TypeChecker_Common.mk_by_tactic tactic tmp))))
  )

let is_comp_ascribed_reflect (e : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) : ((FStarC_Ident.lident * (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) option =
  (let tmp = (FStarC_Syntax_Subst.compress e) in
  let tmp1 = (tmp).FStarC_Syntax_Syntax.n in
  (match tmp1 with
    | (FStarC_Syntax_Syntax.Tm_ascribed ({ FStarC_Syntax_Syntax.tm = e1; asc = (FStar_Pervasives.Inr (tmp2)); asc1 = tmp3; asc2 = tmp4; eff_opt = tmp5; _ })) -> (let tmp6 = (FStarC_Syntax_Subst.compress e1) in
      let tmp7 = (tmp6).FStarC_Syntax_Syntax.n in
      (match tmp7 with
        | (FStarC_Syntax_Syntax.Tm_app (tmp8)) -> (let tmp9 = (FStarC_Syntax_Util.head_and_args_full e1) in
          (match tmp9 with
            | (head, args) -> (match args with
                | ((e2, aqual) :: []) -> (let tmp10 = (FStarC_Syntax_Subst.compress head) in
                  let tmp11 = (tmp10).FStarC_Syntax_Syntax.n in
                  (match tmp11 with
                    | (FStarC_Syntax_Syntax.Tm_constant ((FStarC_Const.Const_reflect (l)))) -> (Some ((l, e2, aqual)))
                    | tmp12 -> None
                  ))
                | tmp10 -> None
              )
          ))
        | tmp8 -> None
      ))
    | tmp2 -> None
  ))

let comp_check_expected_typ (env : FStarC_TypeChecker_Env.env) (e : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) (lc : (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.comp_typ) FStarC_Syntax_Syntax.syntax * FStarC_TypeChecker_Common.guard_t) =
  (match (FStarC_TypeChecker_Env.expected_typ env) with
    | None -> (e, lc, FStarC_TypeChecker_Common.fStarC_Class_Monoid_mzero__guard_t)
    | (Some ((t, use_eq))) -> (let tmp = (FStarC_TypeChecker_Util.maybe_coerce_lc env e lc t) in
      (match tmp with
        | (e1, lc1, g_c) -> (let tmp1 = (FStarC_TypeChecker_Util.weaken_result_typ env e1 (lc1, FStarC_TypeChecker_Common.fStarC_Class_Monoid_mzero__guard_t) t use_eq) in
          (match tmp1 with
            | (e2, lc2, g) -> (let tmp2 = (FStarC_TypeChecker_Common.fStarC_Class_Monoid_op_Plus_Plus__guard_t g g_c) in
              (e2, lc2, tmp2))
          ))
      ))
  )

