let rec apply_well_typed (env : FStarC_TypeChecker_Env.env) (t_hd : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) (args : (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) option =
  (if (match args with
    | [] -> true
    | tmp -> false
  ) then (Some (t_hd)) else (let thd = (FStarC_TypeChecker_Normalize.unfold_whnf env t_hd) in
  (match (thd).FStarC_Syntax_Syntax.n with
    | (FStarC_Syntax_Syntax.Tm_arrow (tmp)) -> (let tmp1 = (FStarC_Syntax_Util.arrow_formals_comp_ln_strict thd) in
      (match tmp1 with
        | (bs, c) -> (let n_args = (FStarC_List.length args) in
          let n_bs = (FStarC_List.length bs) in
          let tmp2 = (if (Prims.op_Less n_args n_bs) then (let tmp2 = (FStarC_Util.first_N n_args bs) in
            (match tmp2 with
              | (bs1, rest) -> (let t = (FStarC_Syntax_Syntax.mk_Tm_arrow rest c (t_hd).FStarC_Syntax_Syntax.pos) in
                let tmp3 = (FStarC_Syntax_Syntax.mk_Total t) in
                let tmp4 = (FStarC_Syntax_Subst.open_comp bs1 tmp3) in
                (match tmp4 with
                  | (bs2, c1) -> (bs2, args, (FStarC_Syntax_Util.comp_result c1), [])
                ))
            )) else (let tmp2 = (FStarC_Syntax_Subst.open_comp bs c) in
            (match tmp2 with
              | (bs1, c1) -> (let tmp3 = (FStarC_List.splitAt n_bs args) in
                (match tmp3 with
                  | (args1, remaining_args) -> (bs1, args1, (FStarC_Syntax_Util.comp_result c1), remaining_args)
                ))
            ))) in
          (match tmp2 with
            | (bs1, args1, t, remaining_args) -> (let subst = (FStarC_List.map2 (fun b a -> (FStarC_Syntax_Syntax.NT ((b).FStarC_Syntax_Syntax.binder_bv, (Custard_FStar_Pervasives_Native.fStar_Pervasives_Native_fst a)))) bs1 args1) in
              let t1 = (FStarC_Syntax_Subst.subst subst t) in
              (apply_well_typed env t1 remaining_args))
          ))
      ))
    | (FStarC_Syntax_Syntax.Tm_refine ({ FStarC_Syntax_Syntax.b = x; phi = tmp; _ })) -> (apply_well_typed env (x).FStarC_Syntax_Syntax.sort args)
    | (FStarC_Syntax_Syntax.Tm_ascribed ({ FStarC_Syntax_Syntax.tm = t; asc = u__1; asc1 = u__2; asc2 = u__3; eff_opt = tmp; _ })) -> (apply_well_typed env t args)
    | tmp -> None
  )))

let rec universe_of_aux__type_of_head (e : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) (retry : bool) (env : FStarC_TypeChecker_Env.env) (hd : (FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax) (args : (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list) : ((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (((FStarC_Syntax_Syntax.term') FStarC_Syntax_Syntax.syntax * (FStarC_Syntax_Syntax.arg_qualifier) option)) list) =
  (let hd1 = (FStarC_Syntax_Subst.compress hd) in
  (match (hd1).FStarC_Syntax_Syntax.n with
    | FStarC_Syntax_Syntax.Tm_unknown -> (FStarC_Effect.failwith "Impossible: universe_of_aux: Tm_app: unexpected head type")
    | (FStarC_Syntax_Syntax.Tm_bvar (tmp)) -> (FStarC_Effect.failwith "Impossible: universe_of_aux: Tm_app: unexpected head type")
    | (FStarC_Syntax_Syntax.Tm_delayed (tmp)) -> (FStarC_Effect.failwith "Impossible: universe_of_aux: Tm_app: unexpected head type")
    | (FStarC_Syntax_Syntax.Tm_fvar (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_name (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_uvar (u__1, u__2)) -> (let tmp = (universe_of_aux env hd1) in
      (tmp, args))
    | (FStarC_Syntax_Syntax.Tm_uinst (u__1, u__2)) -> (let tmp = (universe_of_aux env hd1) in
      (tmp, args))
    | (FStarC_Syntax_Syntax.Tm_ascribed (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_refine (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_constant (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_arrow (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_meta (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_type (tmp)) -> (let tmp1 = (universe_of_aux env hd1) in
      (tmp1, args))
    | (FStarC_Syntax_Syntax.Tm_match ({ FStarC_Syntax_Syntax.scrutinee = tmp; ret_opt = tmp1; brs = (b :: tmp2); rc_opt = tmp3; _ })) -> (let tmp4 = (FStarC_Syntax_Subst.open_branch b) in
      (match tmp4 with
        | (pat, tmp5, tm) -> (let bvs = (FStarC_Syntax_Syntax.pat_bvs pat) in
          let tmp6 = (FStarC_Syntax_Util.head_and_args_full tm) in
          (match tmp6 with
            | (hd2, args') -> (let tmp7 = (FStarC_TypeChecker_Env.push_bvs env bvs) in
              ((universe_of_aux__type_of_head e) retry tmp7 hd2 (FStarC_List.op_At args' args)))
          ))
      ))
    | tmp when retry -> (let e1 = (FStarC_TypeChecker_Normalize.normalize (FStarC_TypeChecker_Env.Beta :: (FStarC_TypeChecker_Env.DoNotUnfoldPureLets :: [])) env e) in
      let tmp1 = (FStarC_Syntax_Util.head_and_args_full e1) in
      (match tmp1 with
        | (hd2, args1) -> ((universe_of_aux__type_of_head e) false env hd2 args1)
      ))
    | tmp -> (let tmp1 = (FStarC_TypeChecker_Env.clear_expected_typ env) in
      (match tmp1 with
        | (env1, tmp2) -> (let env2 = { FStarC_TypeChecker_Env.solver = (env1).FStarC_TypeChecker_Env.solver;
              range = (env1).FStarC_TypeChecker_Env.range;
              curmodule = (env1).FStarC_TypeChecker_Env.curmodule;
              gamma = (env1).FStarC_TypeChecker_Env.gamma;
              gamma_sig = (env1).FStarC_TypeChecker_Env.gamma_sig;
              gamma_cache = (env1).FStarC_TypeChecker_Env.gamma_cache;
              modules = (env1).FStarC_TypeChecker_Env.modules;
              expected_typ = (env1).FStarC_TypeChecker_Env.expected_typ;
